def _run_module(wrapped_cmd, jid, result_path):
    global job_path
    job_path = result_path
    # The controller treats the presence of 'failed' as terminal while polling.
    jwrite({'started': 1, 'finished': 0, 'ansible_job_id': jid})

    # signal grandchild process started and isolated from being terminated
    # by the connection being closed sending a signal to the job group
    _notify_parent(True)

    outdata = ''
    filtered_outdata = ''
    stderr = ''
    try:
        cmd = [to_bytes(c, errors='surrogate_or_strict') for c in shlex.split(wrapped_cmd)]
        # call the module interpreter directly (for non-binary modules)
        # this permits use of a script for an interpreter on non-Linux platforms
        interpreter = _get_interpreter(cmd[0])
        if interpreter:
            cmd = interpreter + cmd
        script = subprocess.Popen(cmd, shell=False, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                  stderr=subprocess.PIPE)

        (outdata, stderr) = script.communicate()
        if PY3:
            outdata = outdata.decode('utf-8', 'surrogateescape')
            stderr = stderr.decode('utf-8', 'surrogateescape')

        (filtered_outdata, json_warnings) = _filter_non_json_lines(outdata)

        result = json.loads(filtered_outdata)

        if json_warnings:
            # merge JSON junk warnings with any existing module warnings
            module_warnings = result.get('warnings', [])
            if not isinstance(module_warnings, list):
                module_warnings = [module_warnings]
            module_warnings.extend(json_warnings)
            result['warnings'] = module_warnings

        if stderr:
            result['stderr'] = stderr
    except Exception as e:
        result = _error_result(
            jid, e, started=1, cmd=wrapped_cmd,
            stdout=to_text(outdata, errors='surrogate_or_strict'),
            stderr=to_text(stderr, errors='surrogate_or_strict'),
            exception=traceback.format_exc(),
        )
    else:
        result['ansible_job_id'] = jid
        result['started'] = 1
        result['finished'] = 1
        result.setdefault('failed', False)

    jwrite(result)


def _record_error(result):
    try:
        jwrite(result)
    except Exception as e:
        result['msg'] += '; could not write job result: %s' % to_text(e)


def _stop_worker(sub_pid):
    """Stop a worker before recording a supervisor failure or removing its files."""
    try:
        waited_pid, unused = os.waitpid(sub_pid, os.WNOHANG)
        if waited_pid:
            return
    except OSError as e:
        if e.errno == errno.ECHILD:
            return

    try:
        os.killpg(sub_pid, signal.SIGKILL)
    except OSError as e:
        if e.errno != errno.ESRCH:
            notice('Could not stop async process group %s: %s' % (sub_pid, to_text(e)))
        try:
            os.kill(sub_pid, signal.SIGKILL)
        except OSError as kill_error:
            if kill_error.errno != errno.ESRCH:
                notice('Could not stop async worker %s: %s' % (sub_pid, to_text(kill_error)))

    try:
        os.waitpid(sub_pid, 0)
    except OSError as e:
        if e.errno != errno.ECHILD:
            notice('Could not reap async worker %s: %s' % (sub_pid, to_text(e)))


def _supervise(sub_pid, time_limit, jid, wrapped_module, preserve_tmp):
    # Keep the notifier until process-group setup succeeds so startup errors
    # can still reach the controller.
    try:
        os.setpgid(sub_pid, sub_pid)
    except OSError as e:
        if e.errno != errno.ESRCH:
            raise
    ipc_notifier.close()

    notice('Start watching %s (%s)' % (sub_pid, time_limit))
    remaining = time_limit
    step = 5
    while os.waitpid(sub_pid, os.WNOHANG) == (0, 0):
        if remaining <= 0:
            notice('Now killing %s' % sub_pid)
            try:
                os.killpg(sub_pid, signal.SIGKILL)
            except OSError as e:
                if e.errno != errno.ESRCH:
                    raise
                # The worker completed between waitpid and killpg.
                os.waitpid(sub_pid, 0)
                break
            os.waitpid(sub_pid, 0)
            jwrite(_error_result(
                jid, 'Async task exceeded time limit of %s seconds (child PID %s)' % (time_limit, sub_pid),
                started=1, child_pid=sub_pid,
            ))
            break
        time.sleep(min(step, remaining))
        remaining -= step

    notice('Done in async supervisor.')
    _cleanup_tmp(wrapped_module, preserve_tmp)
    end(None, 0)


def _run_background(cmd, jid, wrapped_module, preserve_tmp, time_limit):
    started = 0
    sub_pid = None
    try:
        ipc_watcher.close()
        daemonize_self()
        notice('Starting module and watcher')
        sub_pid = os.fork()
        started = 1
        if sub_pid:
            _supervise(sub_pid, time_limit, jid, wrapped_module, preserve_tmp)
        else:
            # Establish the group before Popen so the module also joins it.
            os.setpgid(0, 0)
            notice('Start module (%s)' % os.getpid())
            _run_module(cmd, jid, job_path)
            notice('Module complete (%s)' % os.getpid())
            end(None, 0)
    except SystemExit:
        raise
    except Exception as e:
        error_traceback = traceback.format_exc()
        notice('Async wrapper error: %s' % to_text(e))
        if sub_pid:
            _stop_worker(sub_pid)
        details = {'exception': error_traceback}
        if sub_pid:
            details['child_pid'] = sub_pid
        result = _error_result(jid, 'FATAL ERROR: %s' % to_text(e), started=started,
                               **details)
        _record_error(result)
        _notify_parent(result)
        _cleanup_tmp(wrapped_module, preserve_tmp)
        end(None, 1)


